import React from 'react';
import { IconLoading } from '@arco-design/web-react/icon';
import { connect, mapProps, mapReadPretty } from '@formily/react';
import { InputNumber as ArcoInputNumber, InputNumberProps } from '@arco-design/web-react';
import PreviewText from '../PreviewText';
import { Field } from '@formily/core';


/**
 * 兼容 InputNumber 删除「-」后为 NaN ，formily 内部处理为 null ，导致必填校验失败问题
 */
const InnerArcoInputNumber = (props: InputNumberProps) => {
  const onChange = value => {
    if (value === null || Number.isNaN(value)) {
      // @ts-ignore
      props.onChange?.(undefined);
      return;
    }
    props.onChange?.(value);
  };
  return <ArcoInputNumber {...props} onChange={onChange} />;
};

const InputNumber = connect(
  InnerArcoInputNumber,
  mapProps((props, field: Field) => ({
    ...props,
    suffix: <span>{field?.loading || field?.validating ? <IconLoading /> : props.suffix}</span>,
  })),
  mapReadPretty(PreviewText.Input)
);

export default InputNumber;
